package com.mushafi.app;
import org.json.*;import java.util.*;import com.batoulapps.adhan.*;import com.batoulapps.adhan.data.*;import java.text.*;
public class PrayerNativeTest{
 static int checks=0;static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);checks++;}
 public static void main(String[]args)throws Exception{
  PrayerSettings s=new PrayerSettings(new JSONObject());check(!s.enabled(),"initial alarms disabled until location confirmed");check(s.row("fajr").getInt("iqama")==20&&s.row("dhuhr").getInt("iqama")==20&&s.row("asr").getInt("iqama")==15&&s.row("maghrib").getInt("iqama")==10&&s.row("isha").getInt("iqama")==20,"requested default iqama");
  CalculationParameters params=CalculationMethod.NORTH_AMERICA.getParameters();params.madhab=Madhab.HANAFI;PrayerTimes known=new PrayerTimes(new Coordinates(35.7750,-78.6336),new DateComponents(2015,7,12),params);SimpleDateFormat f=new SimpleDateFormat("HH:mm",Locale.US);f.setTimeZone(TimeZone.getTimeZone("America/New_York"));java.util.Date[] knownTimes={known.fajr,known.sunrise,known.dhuhr,known.asr,known.maghrib,known.isha};String[] expected={"04:42","06:08","13:21","18:22","20:32","21:57"};for(int i=0;i<6;i++)check(f.format(knownTimes[i]).equals(expected[i]),"upstream astronomical reference "+i);
  Calendar date=Calendar.getInstance(TimeZone.getTimeZone("Asia/Riyadh"));date.clear();date.set(2026,9,25,12,0);JSONObject day=PrayerCalculator.calculate(s,date);check(day.getLong("isha")-day.getLong("maghrib")==90*60000L,"Umm Al Qura 90 min");
  JSONObject plusJson=new JSONObject(s.json.toString());plusJson.getJSONObject("offsets").put("dhuhr",7);JSONObject plus=PrayerCalculator.calculate(new PrayerSettings(plusJson),date);check(plus.getLong("dhuhr")-day.getLong("dhuhr")==7*60000L,"manual offsets exact");
  date.set(2026,1,20,12,0);JSONObject ramadan=PrayerCalculator.calculate(s,date);check(ramadan.getBoolean("ramadanAdjustment"),"Ramadan auto via Umm Al Qura calendar");check(ramadan.getLong("isha")-ramadan.getLong("maghrib")==120*60000L,"Ramadan 120 min");plusJson.put("ramadan","off");JSONObject without=PrayerCalculator.calculate(new PrayerSettings(plusJson),date);check(without.getLong("isha")-without.getLong("maghrib")==90*60000L,"Ramadan manual override");
  date.set(2026,9,25,12,0);List<PrayerScheduler.Event> events=PrayerScheduler.events(s,date.getTimeInMillis());for(String k:PrayerSettings.KEYS){long az=0,rem=0,iq=0;for(PrayerScheduler.Event e:events){if(!e.key.equals(k)||e.at<date.getTimeInMillis()-86400000L||e.at>date.getTimeInMillis()+86400000L)continue;JSONObject d=PrayerCalculator.calculate(s,date);long at=d.getLong(k);if(e.kind.equals("adhan")&&e.at==at)az=e.at;if(e.kind.equals("reminder")&&e.at==at+(s.row(k).getInt("iqama")-5)*60000L)rem=e.at;if(e.kind.equals("iqama")&&e.at==at+s.row(k).getInt("iqama")*60000L)iq=e.at;}check(az>0&&rem>az&&iq-rem==300000,"5 minutes before iqama "+k);}
  for(int i=1;i<events.size();i++)check(events.get(i-1).at<=events.get(i).at,"sorted event queue");
  JSONObject shortJson=new JSONObject(s.json.toString());shortJson.getJSONObject("prayers").getJSONObject("maghrib").put("iqama",5);PrayerSettings shortS=new PrayerSettings(shortJson);check(PrayerScheduler.events(shortS,date.getTimeInMillis()).stream().noneMatch(e->e.key.equals("maghrib")&&e.kind.equals("reminder")),"no misleading reminder when iqama <= lead");
  boolean bad=false;try{new PrayerSettings(new JSONObject().put("latitude",91));}catch(Exception e){bad=true;}check(bad,"invalid latitude rejected");bad=false;try{new PrayerSettings(new JSONObject().put("timezone","not/a/zone"));}catch(Exception e){bad=true;}check(bad,"invalid zone rejected");bad=false;try{new PrayerSettings(new JSONObject().put("prayers",new JSONObject().put("fajr",new JSONObject().put("iqama",121))));}catch(Exception e){bad=true;}check(bad,"invalid interval rejected");
  JSONObject polar=new JSONObject(s.json.toString()).put("latitude",80).put("longitude",20).put("timezone","Europe/Oslo");date.set(2026,5,21);bad=false;try{PrayerCalculator.calculate(new PrayerSettings(polar),date);}catch(Exception e){bad=true;}check(bad,"polar no-sunset rejected rather than fabricated");
  System.out.println("PASS native "+checks+" checks: astronomical reference, defaults, offsets, Ramadan and override, all reminders exactly 5 min before iqama, ordered queue, short iqama, validation and polar handling");
 }
}
